<?php declare(strict_types=1);namespace App\Models;use App\Core\Crypto;final class ApiKey extends Model{protected static string $table='api_keys';protected static array $json=['scopes'];protected static bool $timestamps=false;public static function generate(int $S,string $L,array $x=['licenses:read']):array{$H='tvk_'.Crypto::randomToken(24);$c=static::create(['user_id'=>$S,'name'=>$L,'key_prefix'=>substr($H,0,12),'key_hash'=>Crypto::hashToken($H),'scopes'=>$x,'created_at'=>now()]);return['id'=>$c,'plain'=>$H];}public static function authenticate(string $j):?array{$S=static::findBy('key_hash',Crypto::hashToken($j));if($S){static::update((int)$S['id'],['last_used_at'=>now()]);}return $S;}}